import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  CircularProgress,
  Alert,
  Chip,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
} from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { surveyService } from '../services/surveyService';
import { hierarchyService } from '../services/hierarchyService';
import SurveyForm from '../components/surveys/SurveyForm';
import SurveyCard from '../components/surveys/SurveyCard';

const Surveys = () => {
  const { user } = useAuth();
  const [properties, setProperties] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [checklistTemplates, setChecklistTemplates] = useState([]);

  const [selectedProperty, setSelectedProperty] = useState('');
  const [selectedStatus, setSelectedStatus] = useState('');

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [selectedSurvey, setSelectedSurvey] = useState(null);

  useEffect(() => {
    loadData();
  }, [selectedProperty, selectedStatus]);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);

      const organizationId = user?.organizationId;

      // Load data in parallel
      const [propertiesData, surveysData, templatesData] = await Promise.all([
        hierarchyService.getProperties(organizationId),
        surveyService.getSurveys(selectedProperty || undefined, selectedStatus || undefined),
        surveyService.getChecklistTemplates(organizationId),
      ]);

      setProperties(propertiesData);
      setSurveys(surveysData);
      setChecklistTemplates(templatesData);
    } catch (err) {
      setError(err.message || 'Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateSurvey = async (surveyData) => {
    try {
      setLoading(true);
      const newSurvey = await surveyService.createSurvey(surveyData);
      setSurveys(prev => [newSurvey, ...prev]);
      setCreateDialogOpen(false);
    } catch (err) {
      setError(err.message || 'Failed to create survey');
    } finally {
      setLoading(false);
    }
  };

  const handleSurveyAction = async (surveyId, action, data = {}) => {
    try {
      setLoading(true);
      let updatedSurvey;

      switch (action) {
        case 'start':
          updatedSurvey = await surveyService.startSurvey(surveyId);
          break;
        case 'complete':
          updatedSurvey = await surveyService.completeSurvey(surveyId);
          break;
        case 'submit-review':
          updatedSurvey = await surveyService.submitForReview(surveyId);
          break;
        case 'approve':
          updatedSurvey = await surveyService.approveSurvey(surveyId, data.reviewNotes);
          break;
        case 'reject':
          updatedSurvey = await surveyService.rejectSurvey(surveyId, data.reviewNotes);
          break;
        case 'delete':
          await surveyService.deleteSurvey(surveyId);
          setSurveys(prev => prev.filter(s => s.id !== surveyId));
          return;
        default:
          throw new Error('Unknown action');
      }

      if (updatedSurvey) {
        setSurveys(prev => prev.map(s => s.id === surveyId ? updatedSurvey : s));
      }
    } catch (err) {
      setError(err.message || `Failed to ${action} survey`);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'DRAFT':
        return 'default';
      case 'IN_PROGRESS':
        return 'warning';
      case 'COMPLETED':
        return 'success';
      case 'REVIEW_PENDING':
        return 'info';
      case 'APPROVED':
        return 'success';
      case 'REJECTED':
        return 'error';
      default:
        return 'default';
    }
  };

  return (
    <Box m={3}>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">
          Surveys
        </Typography>
        <Button
          variant="contained"
          onClick={() => setCreateDialogOpen(true)}
          disabled={!properties.length}
        >
          Create Survey
        </Button>
      </Box>

      {error && (
        <Alert severity="error" onClose={() => setError(null)} sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {/* Filters */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Property</InputLabel>
                <Select
                  value={selectedProperty}
                  onChange={(e) => setSelectedProperty(e.target.value)}
                  label="Property"
                >
                  <MenuItem value="">All Properties</MenuItem>
                  {properties.map((property) => (
                    <MenuItem key={property.id} value={property.id}>
                      {property.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={4}>
              <FormControl fullWidth>
                <InputLabel>Status</InputLabel>
                <Select
                  value={selectedStatus}
                  onChange={(e) => setSelectedStatus(e.target.value)}
                  label="Status"
                >
                  <MenuItem value="">All Statuses</MenuItem>
                  <MenuItem value="DRAFT">Draft</MenuItem>
                  <MenuItem value="IN_PROGRESS">In Progress</MenuItem>
                  <MenuItem value="COMPLETED">Completed</MenuItem>
                  <MenuItem value="REVIEW_PENDING">Review Pending</MenuItem>
                  <MenuItem value="APPROVED">Approved</MenuItem>
                  <MenuItem value="REJECTED">Rejected</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={4}>
              <Typography variant="body2" color="textSecondary">
                {surveys.length} survey{surveys.length !== 1 ? 's' : ''} found
              </Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Surveys List */}
      {loading ? (
        <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
          <CircularProgress />
        </Box>
      ) : surveys.length > 0 ? (
        <Grid container spacing={3}>
          {surveys.map((survey) => (
            <Grid item xs={12} md={6} lg={4} key={survey.id}>
              <SurveyCard
                survey={survey}
                onAction={handleSurveyAction}
                userRole={user?.role}
                loading={loading}
              />
            </Grid>
          ))}
        </Grid>
      ) : (
        <Card>
          <CardContent>
            <Typography variant="h6" align="center" color="textSecondary">
              No surveys found
            </Typography>
            <Typography variant="body2" align="center" color="textSecondary" sx={{ mt: 1 }}>
              {selectedProperty || selectedStatus
                ? 'Try adjusting your filters or create a new survey'
                : 'Create your first survey to get started'}
            </Typography>
          </CardContent>
        </Card>
      )}

      {/* Create Survey Dialog */}
      <Dialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>Create New Survey</DialogTitle>
        <DialogContent>
          <SurveyForm
            properties={properties}
            checklistTemplates={checklistTemplates}
            onSubmit={handleCreateSurvey}
            onCancel={() => setCreateDialogOpen(false)}
            loading={loading}
          />
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default Surveys;
